import anthropic
import json
import ledger
from ledger import PostError

def transfer(acct: str, cents: int, reason: str) -> int:
    """Transfer cents to account and return the entry id."""
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "ledger_post",
            "description": "Post an amount to a ledger account with a memo",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents to post"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo for this transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with memo '{reason}' and tell me the entry id"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use = next(block for block in response.content if block.type == "tool_use")
        tool_name = tool_use.name
        tool_input = tool_use.input

        if tool_name == "ledger_post":
            try:
                entry_id = ledger.post(
                    account=tool_input["account"],
                    amount=tool_input["amount"],
                    memo=tool_input["memo"]
                )
                tool_result = {
                    "type": "tool_result",
                    "tool_use_id": tool_use.id,
                    "content": f"Successfully posted. Entry ID: {entry_id}"
                }
            except PostError as e:
                tool_result = {
                    "type": "tool_result",
                    "tool_use_id": tool_use.id,
                    "content": f"Error posting to ledger: {str(e)}",
                    "is_error": True
                }

        messages.append({"role": "assistant", "content": response.content})
        messages.append({"role": "user", "content": [tool_result]})

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

    final_text = next(
        (block.text for block in response.content if hasattr(block, "text")),
        None
    )

    import re
    match = re.search(r"Entry ID[:\s]+(\d+)", final_text or "")
    if match:
        return int(match.group(1))

    raise ValueError("Failed to extract entry ID from response")
